window.products.push({"id":149014,"name":"Whirlpool W10310006A Range Cooking Adhesive","category":"homeandappliances","retail price":68.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/61VJsqXn8iL._AC_SL1280_.jpg","description":"This universal Range Cooking Adhesive includes 1 LOCTITE AA 330 adhesive tube and 1 LOCTITE SF 7387 activator tube. LOCTITE AA 330 is a no-mix, pale-yellow, general purpose structural bonder which is ideal for bonding dissimilar substrates like PVC, phenolic and acrylic compounds. It is a medium to high viscosity product that has good impact resistance as well as a service temperature range up to +100°C. It requires an activator, LOCTITE SF 7387.","images":["https://m.media-amazon.com/images/I/61VJsqXn8iL._AC_SL1280_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Whirlpool","source_asin":"B008DJPT8S","category_path":"Home & Appliances"},"sku":"BM-149014","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B008DJPT8S","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Appliances.jsonl","source_asin":"B008DJPT8S","price_pending":true,"merchant_ready":false});
